from src.intervals import merge_intervals, max_non_overlapping, is_covered


def test_merge_basic():
    result = merge_intervals([[1, 3], [2, 6], [8, 10], [15, 18]])
    assert result == [[1, 6], [8, 10], [15, 18]]


def test_merge_adjacent():
    result = merge_intervals([[1, 4], [4, 5]])
    assert result == [[1, 5]]


def test_max_non_overlapping():
    assert max_non_overlapping([[1, 3], [2, 4], [3, 5]]) == 2
    assert max_non_overlapping([[1, 2], [3, 4], [5, 6]]) == 3


def test_is_covered_true():
    assert is_covered([[1, 4], [4, 8]], [2, 7]) is True


def test_is_covered_false():
    assert is_covered([[1, 3], [5, 8]], [2, 6]) is False

